// Photo asset "bt-speaker" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/bt-speaker.js"></script>
//   <img data-asset="bt-speaker" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "bt-speaker": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="bt-speaker"]').forEach(function (img) { img.src = window.ASSETS["bt-speaker"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
